import React, { useState } from 'react'
import './App.css';
import Preview from './components/preview';
import Message from './components/message';
import NotesContainer from './components/notes/notesContainer'
import NotesList from './components/notes/notesList';
import Note from './components/notes/note';
function App() {

  const [notes, setnotes] = useState([])
  const [title, setTitle] = useState('')
  const [content, setContent] = useState('')
  const [selectedNote, setSelectedNote] = useState(null)
  const [creating, setCreating] = useState(false)
  const [editing, setEditing] = useState(false)

//حفظ ملاحظة جديده
  const saveNoteHandler = ()=>{
    const note = {
      id: `${new Date()}`,
      title: title,
      content: content
    }
    const updateNote = [...notes,note]
    setnotes(updateNote)
    setCreating(false)
    setSelectedNote(note.id)
    setContent('')
    setTitle('')
  }

  //انشاء صفحة ملاحظه جديده
  const creatingNotePreview =()=>{
    setCreating(true)
    setEditing(false)
    setContent('')
    setTitle('')
  }

  //الانتقال لوضع تعديل الملاحظه
    const editNoteHandler = ()=>{
    const note = notes.find(note=> note.id === selectedNote)
    setEditing(true)
    setContent(note.content)
    setTitle(note.title)
  }

  //لتعديل الملاحظات
  const updateNoteHandler =()=>{
    const updatedNotes = [...notes]
    const noteIndex = notes.findIndex(note => note.id === selectedNote)
    updatedNotes[noteIndex] = {
      id:selectedNote,
      content:content,
      title:title
    }
    setnotes(updatedNotes)
    setEditing(false)
    setContent('')
    setTitle('')

  }


  //اختيار العنصر
  const noteClickedHandler = (noteid) =>{
    setSelectedNote(noteid)
    console.log(noteid)
  }


  const getAddNote = () => {
    return (
      <div>
        <h2>إضافة ملاحظة جديدة</h2>
        <div>
          <input
            type="text"
            name="title"
            className="form-input mb-30"
            placeholder="العنوان"
            value={title}
            //لتغيير القيمة التي تظهر على الشاشه
            onChange={(e) => {setTitle(e.target.value)}}
            />

          <textarea
            rows="10"
            name="content"
            className="form-input"
            placeholder="النص"
            value={content}
            //لتغيير القيمة التي تظهر على الشاشه
            onChange={(e) => {setContent(e.target.value)}}
            />


          <a onClick={saveNoteHandler} href="#" className="button green">
            حفظ
          </a>
        </div>
      </div>
    );
  };

  const getPreview = () => {
    if (notes.length === 0){
      return <Message title="لا يوجد ملاحظات"/>
    }
    if (!selectedNote) {
      return <Message title="الرجاء اختيار ملاحظة"/>
    }

    const note = notes.find(note =>{
      return note.id === selectedNote
    })

    let noteDisplay =(
      <div>
        <h2>{note.title}</h2>
        <p>{note.content}</p>
      </div>
    )

    if (editing){
      noteDisplay = (
      <div>
        <h2>تعديل الملاحظه</h2>
        <form>
          <input
              type="text"
              name="title"
              className="form-input mb-30"
              placeholder="العنوان"
              value={title}
              //لتغيير القيمة التي تظهر على الشاشه
              onChange={(e) => {setTitle(e.target.value)}}
            />

            <textarea
              rows="10"
              name="content"
              className="form-input"
              placeholder="النص"
              value={content}
              //لتغيير القيمة التي تظهر على الشاشه
              onChange={(e) => {setContent(e.target.value)}}
            />

             <a onClick={updateNoteHandler} href="#" className="button green">
            تعديل
          </a>
        </form>
      </div>
      )
    }
    return (
      <div>

        {!editing && <div className="note-operations">
          <a href="#" onClick={editNoteHandler}>
            <i className="fa fa-pencil-alt" />
          </a>
          <a href="#">
            <i className="fa fa-trash" />
          </a>
        </div>
        }

        {noteDisplay}

      </div>
    );
  };

  return (
    <div className="App">
      <NotesContainer>
        <NotesList>
          {notes.map(note => (
            <Note 
              key={note.id}
              title={note.title}
              onClicked={() => noteClickedHandler(note.id)}
              active={selectedNote===note.id} />))}
        </NotesList>
        <button className="add-btn" onClick={creatingNotePreview}>+</button>
      </NotesContainer>
      <Preview className="preview-section">{creating? getAddNote():getPreview()}</Preview>
    </div>
  );
}

export default App;
